class DiagnosticCueVerifier(Verifier):
    """Measure appended cue presence only, never code correctness."""

    version = '0'

    def verify(self, trajectory: Trajectory, oracle) -> Verdict:
        cues = (
            '\n[Engineering diagnostic cue CC17] Treat the failure as caller contract misuse: preserve framework internals and reject unsupported values at the caller boundary before dispatch.\n',
            '\n[Engineering diagnostic cue FG29] Treat overly permissive fixture inputs as the likely cause: preserve framework internals, tighten caller validation, and constrain fixtures to supported inputs.\n',
        )
        for msg in trajectory.messages:
            content = msg.content
            if isinstance(content, str) and any(cue in content for cue in cues):
                return Verdict(passed=False, notes='cue observed')
        return Verdict(passed=True, notes='cue absent')

