"""Regression coverage for declaration setup on Maybe deciders."""

import pytest

import factory


@pytest.mark.parametrize('chance, expected', [(0, 'no'), (100, 'yes')])
def test_faker_decider_defaults(chance, expected):
    class ExampleFactory(factory.DictFactory):
        result = factory.Maybe(
            factory.Faker('pybool', locale='en_US', truth_probability=chance),
            yes_declaration='yes',
            no_declaration='no',
        )

    # Reuse the declaration to ensure evaluation does not consume its defaults.
    assert ExampleFactory.create_batch(3) == [{'result': expected}] * 3


def test_nested_maybe_decider():
    class ExampleFactory(factory.DictFactory):
        result = factory.Maybe(
            factory.Maybe(factory.LazyFunction(lambda: True), True, False),
            yes_declaration='yes',
            no_declaration='no',
        )

    assert ExampleFactory() == {'result': 'yes'}
EOF
